/**
 * Local wallet persistence for recovery-phrase wallets.
 *
 * Threat model and choices:
 * - A recovery phrase is wallet-equivalent, so it must never be written to
 *   localStorage (which is plaintext, synced by some extensions and trivially
 *   readable by any script on the origin).
 * - This build has no application backend, so the mnemonic is encrypted with
 *   AES-GCM using a non-extractable 256-bit key generated by WebCrypto. The key
 *   and ciphertext live in IndexedDB. A non-extractable key cannot be read out
 *   of the browser, so stored bytes alone do not reveal the phrase.
 * - This protects at-rest storage, not the running page: any successful XSS or
 *   malicious extension with page access can ask the browser to decrypt. A
 *   non-extractable key still prevents silent exfiltration of the raw key.
 * - When IndexedDB/WebCrypto is unavailable the mnemonic is kept in memory for
 *   the current tab only. It is never persisted in plaintext; the recovery
 *   phrase remains the cross-session fallback.
 */

import { logger, LogCategory } from './logger';

const DB_NAME = 'vendly-wallet';
const DB_VERSION = 1;
const STORE_NAME = 'vault';
const KEY_RECORD_ID = 'wallet-key';
const MNEMONIC_RECORD_ID = 'wallet-mnemonic';
const LEGACY_LOCAL_STORAGE_KEY = 'walletMnemonic';

export interface EncryptedPayload {
  iv: Uint8Array;
  data: ArrayBuffer;
}

interface EncryptedRecord extends EncryptedPayload {
  updatedAt: number;
}

/** Only kept when the browser cannot persist an encrypted record. */
let memoryMnemonic: string | null = null;

function hasWebCrypto(): boolean {
  return typeof crypto !== 'undefined' && typeof crypto.subtle !== 'undefined';
}

function hasIndexedDb(): boolean {
  return typeof indexedDB !== 'undefined' && hasWebCrypto();
}

function readLegacyMnemonic(): string | null {
  try {
    return localStorage.getItem(LEGACY_LOCAL_STORAGE_KEY);
  } catch {
    return null;
  }
}

function removeLegacyMnemonic(): void {
  try {
    localStorage.removeItem(LEGACY_LOCAL_STORAGE_KEY);
  } catch {
    // Storage may be unavailable (private mode); nothing to clean up.
  }
}

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB open failed'));
    request.onblocked = () => reject(new Error('IndexedDB open blocked'));
  });
}

function requestToPromise<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB request failed'));
  });
}

function transactionDone(tx: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error ?? new Error('IndexedDB transaction failed'));
    tx.onabort = () => reject(tx.error ?? new Error('IndexedDB transaction aborted'));
  });
}

async function readRecord<T>(id: string): Promise<T | undefined> {
  const db = await openDatabase();
  try {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const value = await requestToPromise(tx.objectStore(STORE_NAME).get(id));
    await transactionDone(tx);
    return value as T | undefined;
  } finally {
    db.close();
  }
}

async function writeRecord(id: string, value: unknown): Promise<void> {
  const db = await openDatabase();
  try {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(value, id);
    await transactionDone(tx);
  } finally {
    db.close();
  }
}

async function deleteRecord(id: string): Promise<void> {
  const db = await openDatabase();
  try {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).delete(id);
    await transactionDone(tx);
  } finally {
    db.close();
  }
}

async function getOrCreateKey(): Promise<CryptoKey> {
  const existing = await readRecord<CryptoKey>(KEY_RECORD_ID);
  if (existing) return existing;

  const key = await crypto.subtle.generateKey(
    { name: 'AES-GCM', length: 256 },
    false, // non-extractable: raw key bytes never leave WebCrypto
    ['encrypt', 'decrypt'],
  );
  await writeRecord(KEY_RECORD_ID, key);
  return key;
}

/** Encrypt a string with AES-GCM. Exported for tests. */
export async function encryptString(
  key: CryptoKey,
  plaintext: string,
): Promise<EncryptedPayload> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const data = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv: iv as unknown as BufferSource },
    key,
    new TextEncoder().encode(plaintext),
  );
  return { iv, data };
}

/** Decrypt an AES-GCM payload. Exported for tests. */
export async function decryptString(
  key: CryptoKey,
  payload: EncryptedPayload,
): Promise<string> {
  const plaintext = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: payload.iv as unknown as BufferSource },
    key,
    payload.data,
  );
  return new TextDecoder().decode(plaintext);
}

/**
 * Persist a recovery phrase for automatic reconnect.
 * Returns true when an encrypted record was written; false means the phrase is
 * only available in memory for this tab.
 */
export async function saveMnemonic(mnemonic: string): Promise<boolean> {
  memoryMnemonic = mnemonic;
  removeLegacyMnemonic();

  if (!hasIndexedDb()) {
    logger.warn(
      LogCategory.AUTH,
      'Secure wallet storage unavailable; keeping wallet in memory for this session only',
    );
    return false;
  }

  try {
    const key = await getOrCreateKey();
    const payload = await encryptString(key, mnemonic);
    const record: EncryptedRecord = { ...payload, updatedAt: Date.now() };
    await writeRecord(MNEMONIC_RECORD_ID, record);
    return true;
  } catch (e) {
    logger.warn(LogCategory.AUTH, 'Failed to persist encrypted wallet; using session memory only', {
      error: e instanceof Error ? e.message : String(e),
    });
    return false;
  }
}

/**
 * Load the stored recovery phrase, migrating and deleting any legacy plaintext
 * record left by older builds.
 */
export async function loadMnemonic(): Promise<string | null> {
  const legacy = readLegacyMnemonic();
  if (legacy) {
    await saveMnemonic(legacy);
    removeLegacyMnemonic();
    return legacy;
  }

  if (memoryMnemonic) return memoryMnemonic;

  if (!hasIndexedDb()) return null;

  try {
    const record = await readRecord<EncryptedRecord>(MNEMONIC_RECORD_ID);
    if (!record) return null;
    const key = await getOrCreateKey();
    const mnemonic = await decryptString(key, {
      iv: new Uint8Array(record.iv),
      data: record.data,
    });
    memoryMnemonic = mnemonic;
    return mnemonic;
  } catch (e) {
    logger.error(LogCategory.AUTH, 'Stored wallet could not be decrypted', {
      error: e instanceof Error ? e.message : String(e),
    });
    return null;
  }
}

/** Remove the stored recovery phrase from IndexedDB, legacy storage and memory. */
export async function clearMnemonic(): Promise<void> {
  memoryMnemonic = null;
  removeLegacyMnemonic();

  if (!hasIndexedDb()) return;

  try {
    await deleteRecord(MNEMONIC_RECORD_ID);
  } catch (e) {
    logger.warn(LogCategory.AUTH, 'Failed to remove stored wallet record', {
      error: e instanceof Error ? e.message : String(e),
    });
  }
}

/** Test helper: drop the in-memory copy only. */
export function resetMemoryMnemonicForTests(): void {
  memoryMnemonic = null;
}
